-- El recargo por ciudad ya NO se cobra en el momento de la solicitud ni se elige la ciudad al
-- comprar (eso se deshace aquí) — se acumula como deuda pendiente del cliente y se cobra
-- automáticamente en su siguiente compra en Comprar Servicios.
ALTER TABLE "ordenes_compra" DROP COLUMN "id_ciudad";
ALTER TABLE "orden_compra_items" DROP COLUMN "recargo_ciudad";

ALTER TABLE "ordenes_compra" ADD COLUMN "monto_recargos_pendientes" NUMERIC(15,2) NOT NULL DEFAULT 0;

CREATE TABLE "recargos_pendientes" (
  "id_recargo_pendiente" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "id_cliente" INTEGER NOT NULL,
  "id_candidato" BIGINT NOT NULL,
  "id_proceso" INTEGER NOT NULL,
  "id_ciudad" INTEGER NOT NULL,
  "monto" NUMERIC(15,2) NOT NULL,
  "estado" VARCHAR(20) NOT NULL DEFAULT 'PENDIENTE',
  "id_orden_compra" BIGINT,
  "fecha_generado" TIMESTAMP NOT NULL DEFAULT now(),
  "fecha_pagado" TIMESTAMP
);
ALTER TABLE "recargos_pendientes" ADD FOREIGN KEY ("id_cliente") REFERENCES "clientes" ("id_cliente");
ALTER TABLE "recargos_pendientes" ADD FOREIGN KEY ("id_candidato") REFERENCES "candidatos" ("id_candidato");
ALTER TABLE "recargos_pendientes" ADD FOREIGN KEY ("id_proceso") REFERENCES "procesos" ("id_proceso");
ALTER TABLE "recargos_pendientes" ADD FOREIGN KEY ("id_ciudad") REFERENCES "ciudades" ("id_ciudad");
ALTER TABLE "recargos_pendientes" ADD FOREIGN KEY ("id_orden_compra") REFERENCES "ordenes_compra" ("id_orden_compra");
